static int copy_resources(struct task_struct *child)
{
    struct mm_struct *mm;
    int error = -ENOMEM;

    mm = dup_mm(child, current->mm);
    if (!mm)
        return error;

    child->mm = mm;
    child->active_mm = mm;
    return 0;
}

static void queue_new_task(struct task_struct *task)
{
    raw_spin_lock(&task->pi_lock);
    task->__state = TASK_RUNNING;
    enqueue_task(task_rq(task), task, ENQUEUE_WAKEUP);
    raw_spin_unlock(&task->pi_lock);
}

static int prepare_child(struct task_struct *child, bool runnable)
{
    int error = copy_resources(child);
    if (error)
        return error;

    if (runnable)
        queue_new_task(child);
    else
        child->__state = TASK_NEW;

    return 0;
}

static void *take_free_object(struct kmem_cache *cache)
{
    struct slab *slab = cache->active;
    void *object = slab->freelist;

    if (!object)
        return refill_cpu_cache(cache);

    slab->freelist = get_freepointer(cache, object);
    slab->inuse++;
    return object;
}

static void release_partial_slab(struct slab *slab)
{
    if (slab->inuse == 0)
        discard_slab(slab);
}

static void *refill_cpu_cache(struct kmem_cache *cache)
{
    struct slab *slab = find_partial_slab(cache);
    if (!slab)
        slab = allocate_slab(cache);
    if (!slab)
        return NULL;

    cache->active = slab;
    void *object = slab->freelist;
    if (object) {
        slab->freelist = get_freepointer(cache, object);
        slab->inuse++;
    }
    return object;
}

static void return_to_slab(struct kmem_cache *cache, struct slab *slab, void *object)
{
    set_freepointer(cache, object, slab->freelist);
    slab->freelist = object;
    slab->inuse--;
    release_partial_slab(slab);
}

static unsigned long slot_for(const dict *table, const void *key)
{
    const uint64_t hash = table->type->hashFunction(key);
    return hash & (table->size - 1);
}

static dictEntry *lookup(dict *table, const void *key)
{
    unsigned long slot = slot_for(table, key);
    for (dictEntry *entry = table->buckets[slot]; entry;
         entry = entry->next) {
        if (table->type->keyCompare(key, entry->key))
            return entry;
    }

    return NULL;
}

static int insert_if_missing(dict *table, void *key, void *value)
{
    if (lookup(table, key) != NULL)
        return DICT_ERR;

    if (table->used == table->size && expand_table(table) != DICT_OK)
        return DICT_ERR;

    unsigned long slot = slot_for(table, key);
    dictEntry *entry = zmalloc(sizeof(*entry));
    entry->key = key;
    entry->value = value;
    entry->next = table->buckets[slot];
    table->buckets[slot] = entry;
    table->used++;
    return DICT_OK;
}

static void push_element(client *c, robj *list, robj *value)
{
    quicklist *items = list->ptr;
    int where = c->cmd->proc == lpushCommand
        ? QUICKLIST_HEAD
        : QUICKLIST_TAIL;

    quicklistPush(items, value->ptr, sdslen(value->ptr), where);
    signalModifiedKey(c, c->db, c->argv[1]);
    notifyKeyspaceEvent(NOTIFY_LIST, "push", c->argv[1], c->db->id);
    addReplyLongLong(c, quicklistCount(items));
}

static void push_arguments(client *c, robj *list, int first)
{
    if (first >= c->argc) {
        addReplyLongLong(c, quicklistCount(list->ptr));
        return;
    }

    for (int i = first; i < c->argc; i++) {
        robj *value = c->argv[i];
        if (value->type != OBJ_STRING) {
            addReplyError(c, "Expected a string");
            return;
        }
        push_element(c, list, value);
    }
}

void SceneTree::queue_attach(Node *parent, Node *child) {
    ERR_FAIL_NULL(parent);
    ERR_FAIL_NULL(child);
    pending_nodes.push_back({parent, child});
}

void SceneTree::flush_pending_nodes() {
    for (const PendingNode &item : pending_nodes) {
        if (item.child->get_parent() != nullptr) {
            continue;
        }
        item.parent->add_child(item.child);
        item.child->notification(Node::NOTIFICATION_READY);
    }
    pending_nodes.clear();
}

void SceneTree::attach_children(Node *parent, const Vector<Node *> &children) {
    if (parent == nullptr || !parent->is_inside_tree()) {
        return;
    }

    for (Node *child : children) {
        if (child == nullptr || child->get_parent() != nullptr) {
            continue;
        }
        queue_attach(parent, child);
    }

    if (!pending_nodes.is_empty()) {
        flush_pending_nodes();
    }
}

void CanvasItem::draw_preview(const Rect2 &region, const Color &tint) {
    ERR_FAIL_COND(!is_inside_tree());

    const Transform2D local = get_global_transform();
    const Rect2 bounds = local.xform(region);
    RID canvas = get_canvas_item();

    RenderingServer::get_singleton()->canvas_item_add_rect(
        canvas,
        bounds,
        tint
    );
}

void CanvasItem::draw_preview_regions(const Vector<Rect2> &regions, const Color &tint) {
    if (!is_inside_tree()) {
        return;
    }

    const Rect2 viewport = get_viewport_rect();
    for (const Rect2 &region : regions) {
        const Rect2 visible = region.intersection(viewport);
        if (!visible.has_area()) {
            continue;
        }
        draw_preview(visible, tint);
    }
}

type workQueue struct {
    owner *p
    head  uint32
    tail  uint32
}

func nextRunnable(q *workQueue) *g {
    for {
        head := atomic.LoadAcq(&q.head)
        if head == q.tail {
            return nil
        }
        task := q.owner.runq[head%uint32(len(q.owner.runq))].ptr()
        if atomic.CasRel(&q.head, head, head+1) {
            return task
        }
    }
}

func drainRunnable(q *workQueue, limit int) []*g {
    if limit <= 0 {
        return nil
    }

    ready := make([]*g, 0, limit)
    for len(ready) < limit {
        task := nextRunnable(q)
        if task == nil {
            break
        }
        ready = append(ready, task)
    }
    return ready
}

func makeHeader(version uint16, length int) []byte {
    header := make([]byte, 5)
    header[0] = recordTypeHandshake
    header[1] = byte(version >> 8)
    header[2] = byte(version)
    header[3] = byte(length >> 8)
    header[4] = byte(length)
    return header
}

func appendRecord(dst []byte, version uint16, payload []byte) []byte {
    dst = append(dst, makeHeader(version, len(payload))...)
    return append(dst, payload...)
}

func appendRecords(dst []byte, version uint16, payload []byte, limit int) []byte {
    if limit <= 0 || limit > 65535 {
        return dst
    }

    for len(payload) > limit {
        dst = appendRecord(dst, version, payload[:limit])
        payload = payload[limit:]
    }
    if len(payload) != 0 {
        dst = appendRecord(dst, version, payload)
    }
    return dst
}

func matchingNodes(pod *v1.Pod, nodes []*v1.Node) []*v1.Node {
    eligible := make([]*v1.Node, 0, len(nodes))
    for _, node := range nodes {
        if node.Spec.Unschedulable {
            continue
        }
        nodeLabels := labels.Set(node.Labels)
        selector := labels.SelectorFromSet(pod.Spec.NodeSelector)
        if selector.Matches(nodeLabels) {
            eligible = append(eligible, node)
        }
    }
    return eligible
}

func bestMatchingNode(pod *v1.Pod, nodes []*v1.Node) *v1.Node {
    eligible := matchingNodes(pod, nodes)
    var best *v1.Node
    var available int64

    for _, node := range eligible {
        pods := node.Status.Allocatable.Pods().Value()
        if best == nil || pods > available {
            best = node
            available = pods
        }
    }
    return best
}

func (c *Controller) reconcile(ctx context.Context, key string) error {
    namespace, name, err := cache.SplitMetaNamespaceKey(key)
    if err != nil {
        return err
    }

    deployment, err := c.lister.Deployments(namespace).Get(name)
    if apierrors.IsNotFound(err) {
        return nil
    }
    if err != nil {
        return err
    }
    return c.ensureReplicaSet(ctx, deployment)
}

func (c *Controller) ensureReplicaSet(ctx context.Context, deployment *appsv1.Deployment) error {
    sets, err := c.replicaSetsFor(deployment)
    if err != nil {
        return err
    }

    for _, candidate := range sets {
        if templatesMatch(candidate.Spec.Template, deployment.Spec.Template) {
            return c.syncReplicas(ctx, candidate, deployment.Spec.Replicas)
        }
    }
    return c.createReplicaSet(ctx, deployment)
}

fn collect_bindings<'hir>(pattern: &'hir hir::Pat<'hir>) -> Vec<HirId> {
    let mut bindings = Vec::new();

    pattern.walk(|pat| {
        if let hir::PatKind::Binding(_, id, _, _) = pat.kind {
            bindings.push(id);
        }
        true
    });

    bindings.sort_unstable();
    bindings.dedup();
    bindings
}

fn common_bindings<'hir>(
    left: &'hir hir::Pat<'hir>,
    right: &'hir hir::Pat<'hir>,
) -> Vec<HirId> {
    let mut left_ids = collect_bindings(left);
    let right_ids = collect_bindings(right);

    if right_ids.is_empty() {
        return Vec::new();
    }

    left_ids.retain(|id| right_ids.binary_search(id).is_ok());
    left_ids
}

fn register_type<'tcx>(cx: &mut TypeContext<'tcx>, ty: Ty<'tcx>) -> TypeId {
    if let Some(&id) = cx.ids.get(&ty) {
        return id;
    }
    let id = TypeId::from_usize(cx.types.len());
    cx.types.push(ty);
    cx.ids.insert(ty, id);
    id
}

fn find_type(cx: &TypeContext<'_>, id: TypeId) -> Option<Ty<'_>> {
    cx.types.get(id.index()).copied()
}

fn register_types<'tcx>(
    cx: &mut TypeContext<'tcx>,
    input: impl IntoIterator<Item = Ty<'tcx>>,
) -> Vec<TypeId> {
    let mut ids = Vec::new();
    for ty in input {
        let id = register_type(cx, ty);
        if ids.last() != Some(&id) {
            ids.push(id);
        }
    }
    ids
}

fn contains_type(cx: &TypeContext<'_>, id: TypeId) -> bool {
    find_type(cx, id).is_some()
}

