from starlette.responses import JSONResponse

def build_endpoint(handler, response_model=None):
    parameters = signature(handler).parameters
    dependant = get_dependant(call=handler, path="/")

    async def endpoint(request):
        solved = await solve_dependencies(
            request=request,
            dependant=dependant,
            body=await request.json(),
        )
        if solved.errors:
            raise RequestValidationError(solved.errors)
        result = await handler(**solved.values)
        data = serialize_response(response_model, result)
        return JSONResponse(data)

    return endpoint

def serialize_response(response_model, result):
    if response_model is None:
        return jsonable_encoder(result)

    adapter = TypeAdapter(response_model)
    validated = adapter.validate_python(result, from_attributes=True)
    return adapter.dump_python(
        validated,
        mode="json",
        by_alias=True,
        exclude_unset=True,
    )

def describe_operation(route, schema):
    operation = {
        "summary": route.summary or route.name.replace("_", " "),
        "operationId": route.unique_id,
        "responses": {},
    }

    for status, model in route.response_models.items():
        operation["responses"][str(status)] = {
            "description": "Successful Response",
            "content": {
                "application/json": {"schema": schema(model)},
            },
        }

    return operation

def build_operations(routes, schema):
    operations = {}
    for route in routes:
        if not route.include_in_schema:
            continue

        methods = operations.setdefault(route.path_format, {})
        operation = describe_operation(route, schema)
        for method in sorted(route.methods):
            if method != "HEAD":
                methods[method.lower()] = operation.copy()

    return operations

import torch
from torch import Tensor

def normalize_batch(values: Tensor, eps: float = 1e-5) -> Tensor:
    if values.ndim < 2:
        raise ValueError("Expected a batch with a channel dimension")

    reduce = (0, *range(2, values.ndim))
    mean = values.mean(dim=reduce, keepdim=True)
    variance = values.var(dim=reduce, keepdim=True, unbiased=False)
    scale = torch.rsqrt(variance + eps)
    return (values - mean) * scale

def loss(logits: Tensor, targets: Tensor) -> Tensor:
    return torch.nn.functional.cross_entropy(logits, targets)

def batch_objective(values: Tensor, targets: Tensor, classifier) -> Tensor:
    if values.size(0) != targets.size(0):
        raise ValueError("Expected one target per sample")

    normalized = normalize_batch(values)
    logits = classifier(normalized)
    if logits.ndim != 2:
        raise ValueError("Expected one score per class")

    return loss(logits, targets)

def backward_nodes(output, gradients):
    if output.grad_fn is None:
        return

    pending = [(output.grad_fn, gradients)]
    while pending:
        node, upstream = pending.pop()
        downstream = node.apply(*upstream)
        for (edge, index), grad in zip(node.next_functions, downstream):
            if edge is not None and grad is not None:
                pending.append((edge, (grad,)))

def backward_from_loss(output, gradient=None):
    if output.grad_fn is None:
        return

    if gradient is None:
        if output.numel() != 1:
            raise ValueError("Non-scalar outputs need an explicit gradient")
        gradient = output.new_ones(output.shape)

    if gradient.shape != output.shape:
        raise ValueError("Gradient must match the output shape")

    backward_nodes(output, (gradient,))

def align_rows(left, right, fill_value=None):
    index = left.index.union(right.index, sort=False)
    left_indexer = left.index.get_indexer(index)
    right_indexer = right.index.get_indexer(index)

    left_values = take_with_fill(left, left_indexer, fill_value)
    right_values = take_with_fill(right, right_indexer, fill_value)
    return left_values, right_values, index

def group_values(frame, key):
    codes, uniques = factorize(frame[key], sort=False)
    for code, label in enumerate(uniques):
        yield label, frame.iloc[codes == code]

def take_with_fill(frame, indexer, fill_value):
    if len(frame) == 0:
        return np.full((len(indexer), len(frame.columns)), fill_value)

    missing = indexer < 0
    safe_indexer = np.where(missing, 0, indexer)
    values = frame.to_numpy().take(safe_indexer, axis=0)
    if missing.any():
        values = np.where(missing[:, None], fill_value, values)

    return values


def join_groups(frame, key):
    return {label: group for label, group in group_values(frame, key)}

def rolling_mean(values, window):
    if window <= 0:
        raise ValueError("window must be positive")

    series = Series(values, copy=False)
    valid = series.notna()
    counts = valid.cumsum()
    totals = series.fillna(0).cumsum()

    sums = totals - totals.shift(window, fill_value=0)
    counts = counts - counts.shift(window, fill_value=0)
    return sums.div(counts.where(counts > 0))

def rolling_center(values, window):
    series = Series(values, copy=False)
    if series.empty:
        return series

    baseline = rolling_mean(series, window)
    centered = series.sub(baseline)
    observed = series.notna() & baseline.notna()
    return centered.where(observed)


def rolling_spread(values, window):
    deviations = rolling_center(values, window)
    return rolling_mean(deviations.pow(2), window).pow(0.5)

const idlePriority = 5;

function scheduleCallback(root, callback, priority) {
  const expiration = priority === idlePriority ? Infinity : now() + 250;
  const task = {root, callback, expiration};
  taskQueue.push(task);
  requestHostCallback(flushWork);
  return task;
}

function flushWork(deadline) {
  while (taskQueue.length && deadline.timeRemaining() > 0) {
    const task = taskQueue.shift();
    const continuation = task.callback();
    if (typeof continuation === 'function') {
      task.callback = continuation;
      taskQueue.unshift(task);
      break;
    }
  }
}

function requestHostCallback(callback) {
  if (hostCallbackPending) {
    return;
  }

  hostCallbackPending = true;
  channel.port1.onmessage = () => {
    hostCallbackPending = false;
    const end = now() + frameLength;
    callback({timeRemaining: () => Math.max(0, end - now())});
    if (taskQueue.length > 0) {
      requestHostCallback(callback);
    }
  };
  channel.port2.postMessage(null);
}

function scheduleIdleWork(root, callback) {
  return scheduleCallback(root, callback, idlePriority);
}

function reconcileChildren(current, workInProgress, nextChildren, lanes) {
  if (current === null) {
    workInProgress.child = mountChildFibers(workInProgress, null, nextChildren, lanes);
    return;
  }

  const previousChildren = current.child;
  workInProgress.child = reconcileChildFibers(
    workInProgress,
    previousChildren,
    nextChildren,
    lanes,
  );
}

function updateChildren(fiber, children, lanes) {
  const current = fiber.alternate;
  if (current !== null && current.memoizedProps.children === children) {
    fiber.child = current.child;
    return;
  }

  reconcileChildren(current, fiber, children, lanes);
  if (fiber.child !== null) {
    fiber.child.return = fiber;
  }
}

interface Edit {
  start: number;
  end: number;
  text: string;
}

function applyEdits(buffer: TextBuffer, edits: readonly Edit[]): void {
  const ordered = [...edits].sort((a, b) => b.start - a.start);
  for (const edit of ordered) {
    const removed = edit.end - edit.start;
    buffer.delete(edit.start, removed);
    if (edit.text.length > 0) {
      buffer.insert(edit.start, edit.text);
    }
  }
}

function applyTransaction(buffer: TextBuffer, edits: readonly Edit[]): void {
  const ascending = [...edits].sort((a, b) => a.start - b.start);
  let previousEnd = 0;
  for (const edit of ascending) {
    if (edit.start < previousEnd || edit.end < edit.start) {
      throw new RangeError("Overlapping or invalid edits");
    }
    previousEnd = edit.end;
  }

  buffer.beginEdit();
  try {
    applyEdits(buffer, ascending);
  } finally {
    buffer.endEdit();
  }
}

function resolveCommands(registry: CommandRegistry, prefix: string): QuickPickItem[] {
  const normalized = prefix.trim().toLowerCase();
  const result: QuickPickItem[] = [];

  for (const command of registry.getCommands()) {
    const label = command.title ?? command.id;
    if (!label.toLowerCase().includes(normalized)) {
      continue;
    }
    result.push({ label, description: command.id });
  }

  return result;
}

function showCommandPicker(registry: CommandRegistry, picker: QuickPick): Disposable {
  const refresh = (value: string): void => {
    const items = resolveCommands(registry, value);
    picker.items = items.slice(0, 50);
  };

  const subscription = picker.onDidChangeValue(refresh);
  refresh(picker.value);
  picker.show();
  return subscription;
}

class StatusBadge extends StatelessWidget {
  const StatusBadge({super.key, required this.label});

  final String label;

  @override
  Widget build(BuildContext context) {
    final colors = Theme.of(context).colorScheme;
    return DecoratedBox(
      decoration: BoxDecoration(
        color: colors.secondaryContainer,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
        child: buildBadgeLabel(label),
      ),
    );
  }
}

Widget buildStatusSummary(String label, int count) {
  if (count <= 0) {
    return const SizedBox.shrink();
  }

  final summary = count == 1 ? label : '$label ($count)';
  return Align(
    alignment: Alignment.centerLeft,
    child: Semantics(
      label: summary,
      child: StatusBadge(label: summary),
    ),
  );
}

Text buildBadgeLabel(String label) {
  return Text(
    label,
    maxLines: 1,
    overflow: TextOverflow.ellipsis,
  );
}

class _SelectionState extends State<SelectionList> {
  int _selected = 0;

  @override
  Widget build(BuildContext context) {
    return ListView.builder(
      itemCount: widget.items.length,
      itemBuilder: (context, index) {
        return ListTile(
          title: buildSelectionLabel(widget.items[index], index == _selected),
          selected: index == _selected,
          onTap: () => setState(() => _selected = index),
        );
      },
    );
  }
}

Widget buildSelectionPanel(List<String> labels, String title) {
  if (labels.isEmpty) {
    return Center(child: Text(title));
  }

  return Column(
    crossAxisAlignment: CrossAxisAlignment.start,
    children: [
      Text(title),
      Expanded(child: SelectionList(items: labels)),
    ],
  );
}

Text buildSelectionLabel(String label, bool selected) {
  return Text(
    label,
    maxLines: 1,
    overflow: TextOverflow.ellipsis,
    style: selected ? const TextStyle(fontWeight: FontWeight.bold) : null,
  );
}
